import sys, csv, json, importlib.util, numpy as np, pymc as pm
B="/scr/wurgaft/auto-psych/agent_trees/043c9ecd8d452a7b/repo/_runs/cell_1/experiment3/model_loop/"
rows=list(csv.DictReader(open(B+"responses.csv")))
pool=[dict(r, rating="0", trial_index="0") for r in json.load(open(B+"novelty_pool.json"))]
out={}
for path in sys.argv[1:]:
    spec=importlib.util.spec_from_file_location("m",path); m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
    with m.model:
        pm.set_data(m.prepare_observed(rows)); mp=pm.find_MAP(progressbar=False)
        f=m.model.compile_fn(m.model.datalogp, inputs=m.model.value_vars)
        ll=float(f({v.name: mp[v.name] for v in m.model.value_vars}))
        pm.set_data(m.prepare_observed(pool))
        g=m.model.compile_fn(m.model.replace_rvs_by_values([m.model["p_yes"]])[0], inputs=m.model.value_vars, on_unused_input="ignore")
        p=g({v.name: mp[v.name] for v in m.model.value_vars})
    print(path.split('/')[-1], "LL", round(ll,2), {k:np.round(v,3) for k,v in mp.items() if np.size(v)<10 and not k.endswith("__")}, flush=True)
    out[path]=p
ks=list(out); c=out[ks[0]]
for k in ks[1:]: print("RMSE vs", k.split('/')[-1], np.sqrt(np.mean((c-out[k])**2)))

